const body = $json.body || $json;
const clipSeconds = Number(body.clipSeconds || 15);
const clipCount = Number(body.clipCount || Math.ceil((Number(body.totalMinutes || 1) * 60) / clipSeconds));
const mainPrompt = body.mainPrompt || '';
const sceneText = body.scenePrompts || '';
const imageUrls = Array.isArray(body.imageUrls) ? body.imageUrls : (body.imageUrl ? [body.imageUrl] : []);
let scenes = sceneText.split('\n').map(s => s.trim()).filter(Boolean);
if (!scenes.length) scenes = Array.from({ length: clipCount }, (_, i) => `${mainPrompt}\nScene ${i+1}: keep visual continuity, cinematic child-safe motion, clean details.`);
while (scenes.length < clipCount) scenes.push(mainPrompt);
scenes = scenes.slice(0, clipCount);
return [{ json: { job: { mainPrompt, videoType: body.videoType, targetSeconds: Number(body.targetSeconds || clipCount * clipSeconds), clipSeconds, clipCount, model: body.model || 'gen4_turbo', ratio: body.ratio || '1280:720', transition: body.transition || 'fade', negativePrompt: body.negativePrompt || '', imageStyle: body.imageStyle || '', musicMode: body.musicMode || 'upload', musicPrompt: body.musicPrompt || '', musicUrl: body.musicUrl || '', logoUrl: body.logoUrl || '', caption: body.caption || '', musicVolume: Number(body.musicVolume || 0.45), logoPosition: body.logoPosition || 'topRight', autoGenerateScenes: !!body.autoGenerateScenes, autoGenerateImages: !!body.autoGenerateImages, autoRender: !!body.autoRender, loopMode: !!body.loopMode, youtubeMeta: !!body.youtubeMeta, safeKidsMode: !!body.safeKidsMode }, scenes: scenes.map((prompt, index) => ({ index, promptText: prompt, imageUrl: imageUrls.length ? imageUrls[index % imageUrls.length] : '', imagePrompt: `${body.imageStyle || 'high quality cinematic'}: ${prompt}` })) }}];
